C=[]
def card(i,title,kind,primary,support,initial,expected,basis,join,scope,ordinary,evidence,cheap,novelty,docs,scores,access,method):
 C.append(dict(test_id=i,title=title,kind=kind,primary_source_ids=primary,supporting_source_ids=support,initial_observation=initial,expected_observation=expected,logical_or_legal_basis=basis,operational_join=join,timing_geography=scope,ordinary_explanations_and_disqualifiers=ordinary,required_original_records=evidence,next_cheapest_check=cheap,novelty_comparison=novelty,documentation_ids=docs,consequence=scores[0],testability=scores[1],join_route=scores[2],cost_tier=scores[3],access_evidence=access,reproducible_method=method,execution_status='not_executed',positive_finding=False,case_legal_applicability_verified=False,complete_route_feasible=False))
card('Z01','Quantity changes that reverse the competitive price ranking','proposed_new',[52,145],[58],
'IF a public works procurement has at least two compliant priced bids on the same item schedule, and the eventual certified quantities differ from the evaluation quantities.',
'THEN price the actually delivered common basket at each eligible bidder’s contemporaneous submitted bid unit rates, comparing that ranking with the original price ranking (separate from the award decision) and examining how quantities changed.',
'This is a transparent counterfactual cost comparison, not a finding of rigging or proof the rival would have performed the work. A sharp reversal concentrated in items the winner priced unusually high merits examining the change rationale and what was foreseeable at award.',
'OCDS ocid + buyer identifier + contract/lot number → exact procurement reference in the World Bank project documents → bid ID + item code + unit + currency + pricing date → certified item quantities. World Bank project ID alone cannot match a contract. Item numbers local to different schedules are not automatically equivalent.',
'One contract/lot and equivalent scope, quality, delivery obligations and tax basis; compare the version used at award with actual certified work and every approved amendment; separate gates for quantity-dependent rates, fixed charges, changed specifications, rate adjustments and rival performance. Do not transfer US FAR rules to a non-US procurement.',
['Rival disqualified or technically noncompliant','Legitimate unforeseeable scope change','New item or revised specification lacking an equivalent rate','Quantity-dependent discount or rate-adjustment clause','Inflation, exchange, taxes or mobilization priced differently','Nonprice evaluation justified the award','Rival lacked capacity for revised work'],
['Original solicitation and bill of quantities','All compared signed bid schedules and evaluation eligibility','Signed contract and rate-adjustment provisions','Approved change orders and reasons','Certified final item quantities, separating paid from merely authorized quantities','Exact project-to-contract reference'],
'First open a bid tabulation and one implementation document for the same contract number. Stop the arithmetic if rival unit rates, item equivalence or actual quantities are absent; total award values cannot replace them.',
'E03 measures common ownership and E07 funded delivery; this tests how the evaluation quantity basket interacts with competing unit-rate schedules. A changed total alone is not a new test.', ['D01','D02','D03'],[5,2,3,3],
'OCDS stage and bid-extension documentation supports candidate structure, not publisher completeness. No real bid/quantity chain retrieved; World Bank-priced schedules may be undisclosed.',
'For every eligible bidder b, compute original=sum(q0_i*p_bi) and counterfactual=sum(q1_i*p_bi) only on a fully equivalent complete basket. Report adjustments, excluded items and sensitivity; never extrapolate missing prices. A strict reversal requires the winner to have been cheaper than the same comparator originally and dearer later; initial tie-to-loss is reported separately. A reversal is a question about procurement design/change control, not intent.')
card('Z02','An explicit zero-structure resettlement inventory contradicted by dated imagery','proposed_new',[145,103],[58,115],
'IF an operative project inventory expressly states that no physical structures existed within a precisely mapped acquisition or inundation area at a specified inventory observation date or explicitly defined interval.',
'THEN establish independently corroborated physical structures present at the exact claimed date or during the explicitly claimed zero-structure interval, wholly within that same area, reconcile the inventory definition, and inspect later plan revisions.',
'A verified omitted physical asset can undermine the stated impact assessment. Imagery of a structure cannot establish occupancy, the number displaced, ownership, compensation eligibility or an unpaid claim. The test concerns a specific physical inventory statement, not demographic estimation.',
'World Bank project ID → exact document/version/page and project component → inventory polygon and claimed observation date/interval (distinct from legal eligibility cutoff) → Landsat scene/product ID, acquisition timestamp, georegistration and visible object. JRC water history can contextualize later inundation but cannot substitute for the operative acquisition polygon.',
'Project-specific inventory observation date/interval, separately recorded legal eligibility cutoff, and actual acquisition boundary, with image cloud/shadow/resolution sufficient to identify the object. Applicable safeguard framework and cutoff must be established for any later compliance interpretation.',
['Inventory excludes the particular structure class','Mapped component or boundary changed','Object is rock, temporary equipment or model artifact','Earlier structure demolished/relocated/removed before the claimed date','Image timing does not establish presence at the claimed date','Already inventoried in an annex or amended plan','Georegistration puts the object outside the area','Structure existed but no resident or compensation entitlement follows'],
['Original signed/operative inventory and all spatial annexes','Inventory observation date/interval, separate eligibility cutoff and definitions','Contemporaneous image metadata and pixels','Independent corroboration of structure interpretation','Amendments and actual project boundary','Separate claimant/occupancy/compensation records before making those claims'],
'Read the exact inventory sentence and map before downloading imagery. If Landsat cannot resolve the alleged structure, defer or identify a lawful higher-resolution source explicitly; do not treat a detection model as ground truth.',
'C02 estimates exposure around a hazard; R11 follows project/document milestones. This asks whether a particular zero-asset inventory is falsified by a physical counterexample at the claimed date/interval. It is not an additional population-overlay pairing.', ['D04'],[5,1,2,3],
'World Bank framework documentation establishes inventory context; no project inventory or usable image pair sampled. The earlier project-document component sample does not confirm these fields for this predicate.',
'Record the exact claim, polygon and cutoff; require clear evidence of presence at the claimed date/interval; an earlier image alone fails, and any inference of persistence needs independent temporal corroboration. Report only the minimum verified physical counterexamples, positional uncertainty and any ambiguity; do not multiply structures by a population ratio.')
card('Z03','A specific drug advertisement versus the product’s authorized indication','proposed_new',[278,143],[133],
'IF a preserved advertisement directed at Canada makes an affirmative therapeutic indication/population claim for an exactly identified drug product, and the contemporaneous authoritative monograph limits that product to a different indication or explicitly excludes that population.',
'THEN compare the complete creative and landing page with the authorization in force, establishing whether it is promotional advertising, the intended audience, the responsible advertiser and the precise product.',
'Health Canada identifies promotion outside authorized indications as a concern. An ingredient match, an educational discussion or an off-label clinical prescription does not by itself establish improper advertising; case-specific legal assessment remains necessary.',
'Meta ad ID → preserved exact creative and landing-page URL/date → displayed DIN or independently verified brand + strength + dosage form + company → DPD drug_code/DIN → monograph/version/effective date. Ingredient alone is not a product key. Wayback timestamp is capture time, not proof of first publication or audience.',
'Canadian-directed communication, specific audience and actual running dates, with authorization then in force. General commercial ad historical retention and geographic coverage must be checked; no absence inference from an archive search.',
['Disease-awareness message without product promotion','Non-Canadian audience or different national product','Different formulation/strength','Authorization changed before the ad','Full context qualifies a cropped statement','Scientific exchange not advertising','Unaffiliated impersonation or reseller attribution','Off-label prescribing confused with promotion'],
['Complete ad, disclosure and landing page','Audience/geography and run-date evidence','Exact product bridge including DIN where possible','Contemporaneous approved monograph and authorization changes','Advertiser responsibility and promotional-context evidence'],
'Select a creative with a precise product and indication, then verify DIN and monograph. Stop if only ingredient similarity or an undated screenshot is available.',
'H05 compares marketed products to trial evidence; X06 traces who financed an ad. This compares an actual promotional claim with the exact product’s authorized scope. It is not a broad medical efficacy judgment.', ['D05','D06','D07'],[5,2,2,2],
'DPD API documentation confirms DIN and product fields; official advertising guidance read. No ad or monograph paired; Meta historical access remains unverified.',
'Transcribe the full relevant claim with context; separately record product, indication, population, audience and dates. Build a side-by-side comparison to the applicable monograph text, resolving each mismatch and amendment before escalation.')
card('Z04','Apparently incompatible exclusive grants over the same patent right','proposed_new',[5,253],[],
'IF two executed, concurrently operative public agreements purport to grant independent parties exclusivity over the same specific patent right, field of use and territory.',
'THEN reconstruct the grant chain, scope, amendments and conditions to establish whether both exclusive grants can coexist, rather than inferring a conflict from the word exclusive or a shared patent family.',
'A genuine unresolved incompatibility can materially affect investors or a critical technology’s commercialization. Most apparent overlaps can be lawful sublicences, retained fields, territorial divisions or conditional transactions; contractual interpretation is case-specific.',
'EDGAR CIK/accession/exhibit → executed agreement/schedule → exact application/publication/grant number with country and kind code → patent-family/status crosswalk if needed → legal grantor, grantee, field, territory, operative interval and sublicense rights. Patent family membership is not identity of enforceable rights.',
'Rights at the effective/closing dates, not SEC filing date. Same legal right and substantive use/territory; distinguish applications, national grants, continuation claims and ownership from licences.',
['Lawful master licence and sublicense chain','Carved-out field or territory','Successive term or terminated agreement','Closing condition not satisfied','Retained research rights','Different national/continuation claims','Amended or consented grant','Material schedule redacted'],
['Both executed agreements and patent schedules','All amendments/terminations and closing evidence','Grant-chain and sublicense permissions','Exact patent identifiers and rights scope','Unredacted necessary field/territory terms'],
'Read definitions of field, territory and sublicense authority first. One reviewed public exhibit explicitly carves out fields and territories, illustrating why keyword overlap must be rejected. Do not seek a second party until the first right is precisely defined.',
'X09 tests an issuer title assertion against a registry; this tests coexistence of two operative contractual grants. H03 maps research to patents. EPO is identity/scope support; two SEC exhibits can suffice without inventing a separate cross-source allegation.', ['D08','D09'],[4,1,3,3],
'One SEC exhibit was opened to inspect fields and exceptions, not investigate its parties. No conflicting agreement pair found or sought. EPO OPS requires credentials; no registration or API call made. Missing schedules make a candidate non-executable.',
'Represent each grant as (right, grant chain, field, territory, effective interval, conditions). Require verified nonempty overlap in all dimensions and an actual incompatibility after permissions and carve-outs; a shared family or simultaneous exclusive labels fails this test.')
card('REF-DISC01','A lobbyist’s explicit conviction declaration versus the actual judgment','refinement',[117,129],[125],
'IF a registration expressly denies a covered conviction for a listed lobbyist, while an independently verified identity bridge leads to a final federal/state judgment involving a covered offense.',
'THEN compare the actual declaration and amendments with the judgment, applicable filing-date rule and conviction disposition; do not treat a complaint, charge or same name as a conviction.',
'The 2024 published US Code includes a specified conviction disclosure in 2 USC 1603(b)(7), and official guidance revised February 2025 describes it. Those sources do not resolve a specific person’s identity, offense coverage, vacatur or present filing applicability.',
'LDA filing ID and listed lobbyist → independently corroborated person identity → court + docket + judgment document + convicted offense/statute + disposition date. Name-only joins remain provisional; CourtListener search completeness is not established.',
'Federal or state judgment and actual filing-date applicability; current rule changes, amended filings, vacatur and the distinction between person and employer all require review.',
['Different person','Only charges or dismissed case','Noncovered offense','Vacated or otherwise legally altered conviction','Employer convicted rather than lobbyist','Amended disclosure','Declaration field absent because not applicable rather than affirmative denial'],
['Original complete filing and amendments','Final judgment and subsequent disposition','Independent identity corroboration','Covered-offense legal analysis','Applicable statutory version'],
'Check the exact form field and a known judgment’s disposition first. Stop before any publication if the identity bridge is only a matching name.',
'An additional statutory application of the disclosure-consistency family exemplified by X04. Kept as a refinement, not added to new-mechanism totals.', ['D10','D11'],[4,2,1,2],
'Official statutory edition and dated guidance read; no named lobbyist or court record searched. Not a claim of comprehensive current-law verification.',
'Keep identity and legal applicability as separate gates. Require an affirmative incompatible declaration; missing search hits cannot demonstrate disclosure failure.')
for r in C:
 r['source_manifest']=[{k:S[n][k] for k in ['sys_id','name','join_fields','all_ap_ids','file','line_start','line_end','block_sha256']} for n in dict.fromkeys(r['primary_source_ids']+r['supporting_source_ids'])]
 r['score']=10*r['consequence']+3*r['testability']+2*r['join_route']-2*r['cost_tier']
 r['exact_fingerprint']=hashlib.sha256(json.dumps([r['initial_observation'],r['expected_observation'],r['operational_join']]).encode()).hexdigest()
for k,sortkey in [('priority_rank',lambda r:(-r['score'],r['test_id'])),('consequence_rank',lambda r:(-r['consequence'],r['test_id'])),('testability_rank',lambda r:(-r['testability'],r['cost_tier'],r['test_id']))]:
 for i,r in enumerate(sorted(C,key=sortkey),1):r[k]=i
C.sort(key=lambda r:r['priority_rank'])
def export(name,rows):
 (P/(name+'.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows))
 with (P/(name+'.csv')).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(list,dict)) else v for k,v in r.items()} for r in rows)
